CSSBASE:
.at-head,.at-row{display:grid;gap:14px;align-items:center}
.at-row{position:relative;padding:14px 16px;border-bottom:1px solid var(--border-subtle);transition:background var(--dur-fast)}
.at-row:hover{background:var(--surface-sunken)}
.at-search:focus-within,.at-in:focus{border-color:var(--color-primary)!important;box-shadow:0 0 0 3px var(--iris-100)}
.at-modal{position:fixed;inset:0;z-index:80;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(10,10,20,.5);animation:vdFade var(--dur-fast) var(--ease-out)}
.at-sheet{width:min(560px,100%);max-height:88vh;overflow:auto;background:var(--surface-card);border-radius:var(--radius-xl);box-shadow:var(--shadow-xl);animation:vdMore var(--dur-med) var(--ease-out)}
@keyframes vdFade{from{opacity:0}to{opacity:1}}
@media (max-width:720px){
  .at-modal{align-items:flex-end;padding:0}
  .at-sheet{width:100%;max-height:92vh;border-radius:var(--radius-xl) var(--radius-xl) 0 0}
  .at-bar > div{margin-left:0!important;width:100%}
  .at-bar > div > *{flex:1;justify-content:center}
  .at-search{max-width:none!important}
  .av-toast{left:16px;right:16px!important;bottom:16px!important}
}
